import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null || line.isEmpty()) return; StringTokenizer st = new StringTokenizer(line); int x = Integer.parseInt(st.nextToken()); double y = Double.parseDouble(st.nextToken()); if (x % 5 == 0 && (x + 0.50) <= y) { y -= (x + 0.50); } System.out.printf("%.2f", y); } }